# GitHub Copilot Chat Archive Script
# This script helps you systematically archive all GitHub Copilot conversations
# Author: Generated by GitHub Copilot for PDXSMS_V2 project

param(
    [Parameter(Mandatory=$false)]
    [string]$ArchiveDirectory = "docs/copilot-archive",

    [Parameter(Mandatory=$false)]
    [switch]$CreateTemplate = $false,

    [Parameter(Mandatory=$false)]
    [string]$ProjectName = "PDXSMS_V2"
)

# Function to write colored output
function Write-ColorOutput {
    param([string]$Message, [string]$Color = "White")
    Write-Host $Message -ForegroundColor $Color
}

# Function to create archive directory structure
function Initialize-ArchiveStructure {
    param([string]$BaseDir)

    Write-ColorOutput "?? Creating archive directory structure..." "Cyan"

    # Create base directory
    if (!(Test-Path $BaseDir)) {
        New-Item -ItemType Directory -Path $BaseDir -Force | Out-Null
        Write-ColorOutput "? Created base directory: $BaseDir" "Green"
    }

    # Create yearly/monthly structure
    $currentDate = Get-Date
    $year = $currentDate.Year
    $months = @("01-January", "02-February", "03-March", "04-April", "05-May", "06-June",
                "07-July", "08-August", "09-September", "10-October", "11-November", "12-December")

    # Create directories for current and previous year
    foreach ($y in @(($year - 1), $year)) {
        $yearDir = Join-Path $BaseDir $y.ToString()
        if (!(Test-Path $yearDir)) {
            New-Item -ItemType Directory -Path $yearDir -Force | Out-Null
        }

        foreach ($month in $months) {
            $monthDir = Join-Path $yearDir $month
            if (!(Test-Path $monthDir)) {
                New-Item -ItemType Directory -Path $monthDir -Force | Out-Null
            }
        }
    }

    Write-ColorOutput "? Archive structure created successfully!" "Green"
}

# Function to create conversation template
function New-ConversationTemplate {
    param([string]$Topic, [string]$Date, [string]$BaseDir)

    $dateObj = if ($Date) { [DateTime]::Parse($Date) } else { Get-Date }
    $year = $dateObj.Year
    $month = $dateObj.ToString("MM-MMMM")
    $dateStr = $dateObj.ToString("yyyy-MM-dd")

    $fileName = "$dateStr-$($Topic -replace '[^\w\-]', '-').md"
    $filePath = Join-Path $BaseDir "$year/$month/$fileName"

    $template = @"
# GitHub Copilot Chat Session
**Date:** $($dateObj.ToString("yyyy-MM-dd HH:mm:ss"))  
**Project:** $ProjectName - SMS Safety Management System  
**Topic:** $Topic  
**Session Type:** [Development/Debugging/Architecture/Feature/Bug Fix]  

## ?? Session Summary
Brief description of what was accomplished in this session...

## ?? Key Objectives
- [ ] Objective 1
- [ ] Objective 2
- [ ] Objective 3

## ?? Changes Made
### Files Modified:
- `File1.cs` - Description of changes
- `File2.razor` - Description of changes

### New Files Created:
- `NewFile.cs` - Purpose and description

## ?? Key Insights & Learnings
- Insight 1: Description
- Insight 2: Description

## ?? Issues Encountered & Solutions
### Issue 1: [Brief description]
**Problem:** Description of the problem
**Solution:** How it was resolved
**Learning:** What was learned

## ?? Technical Context
- **Framework:** .NET 8
- **Project Type:** Blazor Server
- **Architecture:** Clean Architecture (Domain/Application/Infrastructure/Presentation)
- **Key Technologies:** Entity Framework, MediatR, Radzen UI

## ?? Related Sessions
- Link to related conversations or documentation

## ?? Full Conversation
```
[PASTE THE FULL COPILOT CONVERSATION HERE]

Replace this section with the complete conversation from GitHub Copilot.
Include all questions, responses, code snippets, and explanations.
```

## ?? Session Metrics
- **Duration:** [Approximate time spent]
- **Complexity:** [Low/Medium/High]
- **Files Touched:** [Number]
- **Lines Changed:** [Approximate]

## ?? Keywords for Search
Tags: $Topic, copilot, $ProjectName, $(Get-Date -Format 'yyyy-MM')

---
*Archived from GitHub Copilot Chat on $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')*
"@

    return @{
        FilePath = $filePath
        Content = $template
        FileName = $fileName
    }
}

# Function to save conversation
function Save-Conversation {
    param([string]$Topic, [string]$Content, [string]$Date, [string]$BaseDir)

    $template = New-ConversationTemplate -Topic $Topic -Date $Date -BaseDir $BaseDir

    # Replace the placeholder with actual content if provided
    if ($Content) {
        $finalContent = $template.Content -replace '\[PASTE THE FULL COPILOT CONVERSATION HERE\].*?```', $Content
    } else {
        $finalContent = $template.Content
    }

    # Ensure directory exists
    $dir = Split-Path $template.FilePath -Parent
    if (!(Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }

    # Save the file
    $finalContent | Out-File -FilePath $template.FilePath -Encoding UTF8

    return $template.FilePath
}

