# Function to create bulk import helper
function New-BulkImportHelper {
    param([string]$BaseDir)

    $helperPath = Join-Path $BaseDir "bulk-import-helper.ps1"
    $helperContent = @"
# Bulk Import Helper for Copilot Conversations
# Use this script to quickly add multiple conversations

param([string]`$Topic, [string]`$Date)

if (-not `$Topic) {
    Write-Host "Usage: .\bulk-import-helper.ps1 -Topic 'Description of conversation' -Date '2024-11-03'" -ForegroundColor Yellow
    Write-Host "Then paste your conversation content when prompted" -ForegroundColor Yellow
    exit
}

Write-Host "?? Creating new conversation archive for: `$Topic" -ForegroundColor Green
Write-Host "?? Date: `$Date" -ForegroundColor Cyan
Write-Host ""
Write-Host "?? Please paste your complete Copilot conversation below." -ForegroundColor Yellow
Write-Host "   Press Ctrl+Z then Enter when finished:" -ForegroundColor Yellow
Write-Host ""

`$content = @()
do {
    `$line = Read-Host
    if (`$line -ne `$null) { `$content += `$line }
} while (`$line -ne `$null)

`$conversationText = `$content -join "`n"

# Save the conversation
. .\Archive-CopilotChats.ps1
`$savedPath = Save-Conversation -Topic `$Topic -Content `$conversationText -Date `$Date -BaseDir "."

Write-Host "? Conversation saved to: `$savedPath" -ForegroundColor Green
"@

    $helperContent | Out-File -FilePath $helperPath -Encoding UTF8
    Write-ColorOutput "??? Bulk import helper created: $helperPath" "Green"
}

# Main execution
Write-ColorOutput "?? GitHub Copilot Chat Archive Tool" "Green"
Write-ColorOutput "Project: $ProjectName" "Cyan"
Write-ColorOutput "Archive Directory: $ArchiveDirectory" "Cyan"
Write-ColorOutput ""

try {
    # Initialize archive structure
    Initialize-ArchiveStructure -BaseDir $ArchiveDirectory

    # Create index
    $indexPath = New-ArchiveIndex -BaseDir $ArchiveDirectory

    # Create bulk import helper
    New-BulkImportHelper -BaseDir $ArchiveDirectory

    if ($CreateTemplate) {
        # Create a sample template
        $samplePath = Save-Conversation -Topic "Sample-Conversation" -Date (Get-Date).ToString("yyyy-MM-dd") -BaseDir $ArchiveDirectory
        Write-ColorOutput "?? Sample template created: $samplePath" "Green"
    }

    Write-ColorOutput ""
    Write-ColorOutput "?? Archive setup complete!" "Green"
    Write-ColorOutput ""
    Write-ColorOutput "?? Next Steps:" "Yellow"
    Write-ColorOutput "1. Navigate to your archive directory: $ArchiveDirectory" "White"
    Write-ColorOutput "2. Use bulk-import-helper.ps1 for quick conversation imports" "White"
    Write-ColorOutput "3. Follow the naming convention: YYYY-MM-DD-topic-description.md" "White"
    Write-ColorOutput "4. Update the README.md index as you add conversations" "White"
    Write-ColorOutput ""
    Write-ColorOutput "?? Pro tip: Start with your most recent/important conversations first!" "Cyan"

} catch {
    Write-ColorOutput "? Error: $($_.Exception.Message)" "Red"
    exit 1
}

# Export key functions for use in other scripts
Export-ModuleMember -Function Save-Conversation, New-ConversationTemplate, Initialize-ArchiveStructure